import sys,numpy as np
sys.path.insert(0,'/app/output');from gen import Robot,run_path,DOWN
r=Robot();o=r.get_obs(video='none');p=np.array(o.meta['proprio']['now'][7:14]);
above=np.r_[[-.12,-.155,.12],DOWN];c0=np.r_[[-.12,-.155,.006],DOWN];c1=np.r_[[-.12,-.215,.006],DOWN];
a=run_path(r,p,above,.10,note='practice second line approach');b=run_path(r,above,c0,.035,note='press for wide brush test');c=run_path(r,c0,c1,.025,note='practice wide pressure line');d=run_path(r,c1,np.r_[[-.12,-.215,.12],DOWN],.05,note='lift practice');
e=run_path(r,np.array(d.proprio[-1,7:14]),np.r_[[-.1,.22,.22],DOWN],.10,note='clear practice camera');
from PIL import Image
ob=r.get_obs(cameras=['practice_cam'],video='frames');Image.fromarray(ob.last['practice_cam']).save('/app/output/practice_two_lines.png')
print('steps',a.meta.get('control_steps_chunk'),b.meta.get('control_steps_chunk'),c.meta.get('control_steps_chunk'), 'now',ob.meta['proprio']['now'][7:10])
PY

